{"path": "frontend/src/layout.js", "content": "// ---------------------------------------------------------------------------
// Overlap layout engine
//
// This module is pure (no DOM, no dates beyond simple math). Given a list of
// events that belong to a single day, expressed as minute offsets from the top
// of the day (startMin, endMin), it computes for each event a fractional
// horizontal placement:
//
//   { id, startMin, endMin, left, width }
//
// where `left` and `width` are fractions in [0, 1] of the day-column width.
//
// Algorithm (cluster-based):
//   1. Sort events by start time (then end time).
//   2. Group events into "clusters": maximal sets of transitively overlapping
//      events. A new cluster begins when an event starts at or after the
//      maximum end time seen so far in the current cluster.
//   3. Within a cluster, assign each event the lowest-indexed column whose last
//      event has already ended (greedy by start time). The number of columns a
//      cluster needs is its width divisor.
//   4. Each event's width = 1 / columnsInCluster, left = columnIndex / columns.
//
// This guarantees:
//   * No two blocks overlap (events in the same column never overlap in time;
//     events in different columns are visually separated).
//   * A cluster needing K columns divides the width into K equal parts.
//   * An event overlapping nothing forms a 1-column cluster -> full width,
//     regardless of other clusters earlier/later the same day.
// ---------------------------------------------------------------------------

/**
 * Two intervals overlap iff a.start < b.end AND b.start < a.end.
 * Touching endpoints (a.end === b.start) do NOT overlap.
 */
function overlaps(a, b) {
  return a.startMin < b.endMin && b.startMin < a.endMin;
}

/**
 * Compute layout for a single day's events.
 * @param {Array<{id:any,startMin:number,endMin:number}>} events
 * @returns {Array<{id:any,startMin:number,endMin:number,left:number,width:number,column:number,columns:number}>}
 */
export function layoutDay(events) {
  const sorted = [...events].sort((a, b) => {
    if (a.startMin !== b.startMin) return a.startMin - b.startMin;
    if (a.endMin !== b.endMin) return a.endMin - b.endMin;
    return String(a.id).localeCompare(String(b.id));
  });

  const result = [];
  let cluster = [];
  let clusterMaxEnd = -Infinity;

  const flush = () => {
    if (cluster.length === 0) return;
    layoutCluster(cluster, result);
    cluster = [];
    clusterMaxEnd = -Infinity;
  };

  for (const ev of sorted) {
    // If this event starts at/after the running cluster end, the previous
    // cluster is complete (no transitive overlap can reach further).
    if (cluster.length > 0 && ev.startMin >= clusterMaxEnd) {
      flush();
    }
    cluster.push(ev);
    clusterMaxEnd = Math.max(clusterMaxEnd, ev.endMin);
  }
  flush();

  return result;
}

/**
 * Assign columns greedily within one cluster and push results.
 */
function layoutCluster(cluster, result) {
  // columns[i] holds the endMin of the last event placed in column i.
  const columnEnds = [];
  const assigned = [];

  for (const ev of cluster) {
    let placed = false;
    for (let i = 0; i < columnEnds.length; i++) {
      // The event can reuse a column if it does not overlap that column's
      // current last event (i.e. it starts at/after that event's end).
      if (ev.startMin >= columnEnds[i]) {
        columnEnds[i] = ev.endMin;
        assigned.push({ ev, column: i });
        placed = true;
        break;
      }
    }
    if (!placed) {
      columnEnds.push(ev.endMin);
      assigned.push({ ev, column: columnEnds.length - 1 });
    }
  }

  const columns = columnEnds.length;
  for (const { ev, column } of assigned) {
    result.push({
      id: ev.id,
      startMin: ev.startMin,
      endMin: ev.endMin,
      column,
      columns,
      left: column / columns,
      width: 1 / columns,
    });
  }
}
"}

{"path": "frontend/src/time.js", "content": "// Date / time helpers. All in the browser's local time zone.

export const MINUTES_PER_DAY = 24 * 60;

/** Return the Monday (local) at 00:00 of the week containing `date`. */
export function startOfWeek(date) {
  const d = new Date(date.getFullYear(), date.getMonth(), date.getDate());
  // getDay(): 0 = Sunday ... 6 = Saturday. We want Monday as the first day.
  const dow = (d.getDay() + 6) % 7; // 0 = Monday
  d.setDate(d.getDate() - dow);
  d.setHours(0, 0, 0, 0);
  return d;
}

export function addDays(date, n) {
  const d = new Date(date);
  d.setDate(d.getDate() + n);
  return d;
}

export function addWeeks(date, n) {
  return addDays(date, n * 7);
}

/** Start of the day (local 00:00) containing `date`. */
export function startOfDay(date) {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  return d;
}

export function isSameDay(a, b) {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

/** Minutes from local midnight of `dayStart` to `date`, may be <0 or >1440. */
export function minutesFromDayStart(date, dayStart) {
  return (date.getTime() - dayStart.getTime()) / 60000;
}

const DAY_NAMES = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const MONTH_NAMES = [
  'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
  'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
];

export function dayName(index) {
  return DAY_NAMES[index];
}

export function formatDayHeader(date) {
  return `${date.getDate()} ${MONTH_NAMES[date.getMonth()]}`;
}

export function formatWeekRange(weekStart) {
  const end = addDays(weekStart, 6);
  const startStr = `${weekStart.getDate()} ${MONTH_NAMES[weekStart.getMonth()]}`;
  const endStr = `${end.getDate()} ${MONTH_NAMES[end.getMonth()]} ${end.getFullYear()}`;
  return `${startStr} – ${endStr}`;
}

/** Format a Date as HH:MM (24h, local). */
export function formatHM(date) {
  const h = String(date.getHours()).padStart(2, '0');
  const m = String(date.getMinutes()).padStart(2, '0');
  return `${h}:${m}`;
}

/** Format minutes-from-midnight as HH:MM. */
export function formatMinutes(min) {
  const clamped = Math.max(0, Math.min(MINUTES_PER_DAY, Math.round(min)));
  const h = Math.floor(clamped / 60);
  const m = clamped % 60;
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
}

/**
 * Build a local Date from a day-start date and a minutes-from-midnight value.
 */
export function dateFromDayMinutes(dayStart, minutes) {
  const d = new Date(dayStart);
  d.setMinutes(d.getMinutes() + Math.round(minutes));
  return d;
}

/**
 * Produce the value string for an <input type="datetime-local"> from a Date,
 * using local time.
 */
export function toDatetimeLocalValue(date) {
  const pad = (n) => String(n).padStart(2, '0');
  return (
    `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}` +
    `T${pad(date.getHours())}:${pad(date.getMinutes())}`
  );
}

/** Parse a datetime-local value (local time) into a Date. */
export function fromDatetimeLocalValue(value) {
  if (!value) return null;
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? null : d;
}
"}

{"path": "frontend/src/api.js", "content": "// Thin client over the JSON HTTP API.

const BASE = '/api';

async function handle(res) {
  if (res.status === 204) return null;
  const text = await res.text();
  let body = null;
  if (text) {
    try {
      body = JSON.parse(text);
    } catch {
      body = { error: text };
    }
  }
  if (!res.ok) {
    const message = (body && body.error) || `Request failed (${res.status})`;
    const err = new Error(message);
    err.status = res.status;
    throw err;
  }
  return body;
}

export async function fetchEvents(startIso, endIso) {
  const url = `${BASE}/events?start=${encodeURIComponent(startIso)}&end=${encodeURIComponent(endIso)}`;
  const res = await fetch(url);
  return handle(res);
}

export async function createEvent(payload) {
  const res = await fetch(`${BASE}/events`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });
  return handle(res);
}

export async function updateEvent(id, payload) {
  const res = await fetch(`${BASE}/events/${id}`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });
  return handle(res);
}

export async function deleteEvent(id) {
  const res = await fetch(`${BASE}/events/${id}`, { method: 'DELETE' });
  return handle(res);
}
"}

{"path": "frontend/src/main.js", "content": "import './styles.css';
import { layoutDay } from './layout.js';
import {
  fetchEvents,
  createEvent,
  updateEvent,
  deleteEvent,
} from './api.js';
import {
  MINUTES_PER_DAY,
  startOfWeek,
  addDays,
  addWeeks,
  isSameDay,
  minutesFromDayStart,
  dayName,
  formatDayHeader,
  formatWeekRange,
  formatMinutes,
  dateFromDayMinutes,
  toDatetimeLocalValue,
  fromDatetimeLocalValue,
} from './time.js';

// --- Geometry constants -----------------------------------------------------
// A single hour-row height in pixels. The entire day axis height is derived
// from this single constant so minute-precision placement is consistent.
const HOUR_HEIGHT = 48; // px per hour
const AXIS_HEIGHT = HOUR_HEIGHT * 24; // px for 00:00 -> 24:00
const PX_PER_MIN = AXIS_HEIGHT / MINUTES_PER_DAY;
// Snap drag selection to this many minutes.
const SNAP_MIN = 15;

const state = {
  weekStart: startOfWeek(new Date()),
  events: [], // raw events from API: {id, title, start_at, end_at}
};

const root = document.getElementById('app');

// ---------------------------------------------------------------------------
// Top-level render
// ---------------------------------------------------------------------------
function render() {
  root.innerHTML = '';
  root.appendChild(buildToolbar());
  root.appendChild(buildCalendar());
}

function buildToolbar() {
  const bar = el('header', 'toolbar');

  const nav = el('div', 'toolbar-nav');
  const prev = button('‹ Prev', () => navigate(-1));
  const today = button('Today', goToday);
  const next = button('Next ›', () => navigate(1));
  prev.classList.add('btn');
  today.classList.add('btn');
  next.classList.add('btn');
  nav.append(prev, today, next);

  const title = el('h1', 'toolbar-title');
  title.textContent = formatWeekRange(state.weekStart);

  const spacer = el('div', 'toolbar-spacer');

  bar.append(nav, title, spacer);
  return bar;
}

function navigate(delta) {
  state.weekStart = addWeeks(state.weekStart, delta);
  loadAndRender();
}

function goToday() {
  state.weekStart = startOfWeek(new Date());
  loadAndRender();
}

// ---------------------------------------------------------------------------
// Calendar grid
// ---------------------------------------------------------------------------
function buildCalendar() {
  const calendar = el('div', 'calendar');

  // Header row: empty corner + 7 day headers.
  const header = el('div', 'cal-header');
  header.appendChild(el('div', 'time-gutter-head'));
  const today = new Date();
  for (let i = 0; i < 7; i++) {
    const date = addDays(state.weekStart, i);
    const cell = el('div', 'day-head');
    if (isSameDay(date, today)) cell.classList.add('is-today');
    const name = el('span', 'day-head-name');
    name.textContent = dayName(i);
    const dnum = el('span', 'day-head-date');
    dnum.textContent = formatDayHeader(date);
    cell.append(name, dnum);
    header.appendChild(cell);
  }
  calendar.appendChild(header);

  // Body: scrollable area containing the time gutter + 7 day columns.
  const body = el('div', 'cal-body');

  const gutter = el('div', 'time-gutter');
  gutter.style.height = `${AXIS_HEIGHT}px`;
  for (let h = 0; h <= 24; h++) {
    const label = el('div', 'hour-label');
    label.style.top = `${h * HOUR_HEIGHT}px`;
    label.textContent = `${String(h).padStart(2, '0')}:00`;
    gutter.appendChild(label);
  }
  body.appendChild(gutter);

  const grid = el('div', 'days-grid');
  grid.style.height = `${AXIS_HEIGHT}px`;
  for (let i = 0; i < 7; i++) {
    grid.appendChild(buildDayColumn(i, today));
  }
  body.appendChild(grid);

  calendar.appendChild(body);
  return calendar;
}

function buildDayColumn(dayIndex, today) {
  const dayStart = addDays(state.weekStart, dayIndex);
  const col = el('div', 'day-col');
  col.style.height = `${AXIS_HEIGHT}px`;
  if (isSameDay(dayStart, today)) col.classList.add('is-today');

  // Hour grid lines.
  for (let h = 1; h < 24; h++) {
    const line = el('div', 'hour-line');
    line.style.top = `${h * HOUR_HEIGHT}px`;
    col.appendChild(line);
  }

  // Events for this day.
  const dayEvents = eventsForDay(dayStart);
  const placements = layoutDay(
    dayEvents.map((e) => ({ id: e.id, startMin: e._startMin, endMin: e._endMin }))
  );
  const byId = new Map(dayEvents.map((e) => [e.id, e]));

  for (const p of placements) {
    const ev = byId.get(p.id);
    col.appendChild(buildEventBlock(ev, p));
  }

  // Drag-to-create interaction on empty space.
  attachDragCreate(col, dayStart);

  return col;
}

/**
 * Returns events overlapping [dayStart, dayStart+1day), each annotated with
 * clamped minute offsets _startMin / _endMin within the day.
 */
function eventsForDay(dayStart) {
  const dayEnd = addDays(dayStart, 1);
  const out = [];
  for (const e of state.events) {
    const s = new Date(e.start_at);
    const en = new Date(e.end_at);
    // Overlaps this day?
    if (s < dayEnd && en > dayStart) {
      const startMin = clampMin(minutesFromDayStart(s, dayStart));
      const endMin = clampMin(minutesFromDayStart(en, dayStart));
      if (endMin > startMin) {
        out.push({ ...e, _startMin: startMin, _endMin: endMin });
      }
    }
  }
  return out;
}

function clampMin(m) {
  return Math.max(0, Math.min(MINUTES_PER_DAY, m));
}

function buildEventBlock(ev, placement) {
  const block = el('div', 'event-block');
  const top = placement.startMin * PX_PER_MIN;
  const height = (placement.endMin - placement.startMin) * PX_PER_MIN;

  block.style.top = `${top}px`;
  block.style.height = `${Math.max(height, 1)}px`;
  // Horizontal placement as percentages of the day column width.
  // A tiny gap between adjacent columns keeps borders distinguishable while
  // the blocks together still fill the column.
  const gap = placement.columns > 1 ? 1 : 0; // px gap handled via inset
  block.style.left = `calc(${placement.left * 100}% + ${gap}px)`;
  block.style.width = `calc(${placement.width * 100}% - ${gap * 2}px)`;

  const title = el('div', 'event-title');
  title.textContent = ev.title;
  const time = el('div', 'event-time');
  time.textContent = `${formatMinutes(ev._startMin)} – ${formatMinutes(ev._endMin)}`;

  block.append(title, time);
  block.title = `${ev.title}\n${formatMinutes(ev._startMin)} – ${formatMinutes(ev._endMin)}`;

  block.addEventListener('click', (e) => {
    e.stopPropagation();
    openEditForm(ev);
  });

  return block;
}

// ---------------------------------------------------------------------------
// Drag-to-create
// ---------------------------------------------------------------------------
function attachDragCreate(col, dayStart) {
  let dragging = false;
  let startMin = 0;
  let ghost = null;

  const minutesAt = (clientY) => {
    const rect = col.getBoundingClientRect();
    const y = clientY - rect.top;
    let m = (y / PX_PER_MIN);
    m = Math.round(m / SNAP_MIN) * SNAP_MIN;
    return Math.max(0, Math.min(MINUTES_PER_DAY, m));
  };

  col.addEventListener('mousedown', (e) => {
    // Only start on empty area (not on an event block).
    if (e.target.closest('.event-block')) return;
    if (e.button !== 0) return;
    dragging = true;
    startMin = minutesAt(e.clientY);
    ghost = el('div', 'event-ghost');
    col.appendChild(ghost);
    updateGhost(ghost, startMin, startMin);
    e.preventDefault();
  });

  const onMove = (e) => {
    if (!dragging) return;
    const cur = minutesAt(e.clientY);
    updateGhost(ghost, Math.min(startMin, cur), Math.max(startMin, cur));
  };

  const onUp = (e) => {
    if (!dragging) return;
    dragging = false;
    const cur = minutesAt(e.clientY);
    let a = Math.min(startMin, cur);
    let b = Math.max(startMin, cur);
    if (ghost) {
      ghost.remove();
      ghost = null;
    }
    // A pure click (no real drag) defaults to a 60-minute event.
    if (b - a < SNAP_MIN) {
      b = Math.min(MINUTES_PER_DAY, a + 60);
      if (b === a) a = Math.max(0, b - 60);
    }
    const start = dateFromDayMinutes(dayStart, a);
    const end = dateFromDayMinutes(dayStart, b);
    openCreateForm(start, end);
  };

  col.addEventListener('mousemove', onMove);
  window.addEventListener('mouseup', onUp);
}

function updateGhost(ghost, aMin, bMin) {
  ghost.style.top = `${aMin * PX_PER_MIN}px`;
  ghost.style.height = `${Math.max((bMin - aMin) * PX_PER_MIN, 2)}px`;
  ghost.textContent = `${formatMinutes(aMin)} – ${formatMinutes(bMin)}`;
}

// ---------------------------------------------------------------------------
// Create / edit modal form
// ---------------------------------------------------------------------------
function openCreateForm(start, end) {
  openForm({
    mode: 'create',
    title: '',
    start,
    end,
  });
}

function openEditForm(ev) {
  openForm({
    mode: 'edit',
    id: ev.id,
    title: ev.title,
    start: new Date(ev.start_at),
    end: new Date(ev.end_at),
  });
}

function openForm(opts) {
  closeForm();

  const overlay = el('div', 'modal-overlay');
  overlay.id = 'modal-overlay';

  const modal = el('div', 'modal');
  const h = el('h2', 'modal-title');
  h.textContent = opts.mode === 'create' ? 'New event' : 'Edit event';

  const form = el('form', 'event-form');

  const titleField = labeledInput('Title', 'text', opts.title);
  titleField.input.required = true;
  titleField.input.placeholder = 'Event title';

  const startField = labeledInput('Start', 'datetime-local', toDatetimeLocalValue(opts.start));
  const endField = labeledInput('End', 'datetime-local', toDatetimeLocalValue(opts.end));

  const errorBox = el('div', 'form-error');
  errorBox.style.display = 'none';

  const actions = el('div', 'form-actions');
  const saveBtn = el('button', 'btn btn-primary');
  saveBtn.type = 'submit';
  saveBtn.textContent = 'Save';

  const cancelBtn = el('button', 'btn');
  cancelBtn.type = 'button';
  cancelBtn.textContent = 'Cancel';
  cancelBtn.addEventListener('click', closeForm);

  actions.append(saveBtn);

  if (opts.mode === 'edit') {
    const delBtn = el('button', 'btn btn-danger');
    delBtn.type = 'button';
    delBtn.textContent = 'Delete';
    delBtn.addEventListener('click', async () => {
      try {
        await deleteEvent(opts.id);
        closeForm();
        await loadAndRender();
      } catch (err) {
        showError(errorBox, err.message);
      }
    });
    actions.append(delBtn);
  }
  actions.append(cancelBtn);

  form.append(
    titleField.wrap,
    startField.wrap,
    endField.wrap,
    errorBox,
    actions
  );

  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    const title = titleField.input.value.trim();
    const start = fromDatetimeLocalValue(startField.input.value);
    const end = fromDatetimeLocalValue(endField.input.value);

    if (!title) return showError(errorBox, 'Title must not be empty.');
    if (!start || !end) return showError(errorBox, 'Start and end must be valid.');
    if (!(end.getTime() > start.getTime())) {
      return showError(errorBox, 'End must be after start.');
    }

    const payload = {
      title,
      start_at: start.toISOString(),
      end_at: end.toISOString(),
    };
    try {
      if (opts.mode === 'create') {
        await createEvent(payload);
      } else {
        await updateEvent(opts.id, payload);
      }
      closeForm();
      await loadAndRender();
    } catch (err) {
      showError(errorBox, err.message);
    }
  });

  modal.append(h, form);
  overlay.appendChild(modal);
  overlay.addEventListener('mousedown', (e) => {
    if (e.target === overlay) closeForm();
  });
  document.body.appendChild(overlay);
  titleField.input.focus();

  const onKey = (e) => {
    if (e.key === 'Escape') closeForm();
  };
  document.addEventListener('keydown', onKey);
  overlay._onKey = onKey;
}

function closeForm() {
  const existing = document.getElementById('modal-overlay');
  if (existing) {
    if (existing._onKey) document.removeEventListener('keydown', existing._onKey);
    existing.remove();
  }
}

function showError(box, msg) {
  box.textContent = msg;
  box.style.display = 'block';
}

function labeledInput(labelText, type, value) {
  const wrap = el('label', 'field');
  const span = el('span', 'field-label');
  span.textContent = labelText;
  const input = document.createElement('input');
  input.type = type;
  input.className = 'field-input';
  if (value != null) input.value = value;
  wrap.append(span, input);
  return { wrap, input };
}

// ---------------------------------------------------------------------------
// Data loading
// ---------------------------------------------------------------------------
async function loadAndRender() {
  render(); // render immediately for snappy navigation
  try {
    const weekEnd = addDays(state.weekStart, 7);
    const events = await fetchEvents(
      state.weekStart.toISOString(),
      weekEnd.toISOString()
    );
    state.events = Array.isArray(events) ? events : [];
  } catch (err) {
    console.error('Failed to load events:', err);
    state.events = [];
  }
  render();
}

// ---------------------------------------------------------------------------
// Small DOM helpers
// ---------------------------------------------------------------------------
function el(tag, className) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  return node;
}

function button(text, onClick) {
  const b = document.createElement('button');
  b.textContent = text;
  b.addEventListener('click', onClick);
  return b;
}

// Boot.
loadAndRender();
"}

{"path": "frontend/src/styles.css", "content": ":root {
  --border: #d7dbe3;
  --border-strong: #c2c8d2;
  --bg: #f6f7f9;
  --panel: #ffffff;
  --text: #1f2733;
  --muted: #6b7480;
  --accent: #2f6fed;
  --accent-soft: #e6efff;
  --today: #fff7e6;
  --today-bar: #f5a623;
  --event-bg: #3b82f6;
  --event-bg-2: #2563eb;
  --danger: #e23b3b;
  --hour-height: 48px;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  height: 100%;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica,
    Arial, sans-serif;
  color: var(--text);
  background: var(--bg);
}

#app {
  display: flex;
  flex-direction: column;
  height: 100vh;
}

/* Toolbar ----------------------------------------------------------------- */
.toolbar {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 10px 16px;
  background: var(--panel);
  border-bottom: 1px solid var(--border);
  flex: 0 0 auto;
}

.toolbar-nav {
  display: flex;
  gap: 8px;
}

.toolbar-title {
  font-size: 18px;
  font-weight: 600;
  margin: 0;
}

.toolbar-spacer {
  flex: 1;
}

.btn {
  font: inherit;
  padding: 6px 12px;
  border: 1px solid var(--border-strong);
  background: var(--panel);
  color: var(--text);
  border-radius: 6px;
  cursor: pointer;
}

.btn:hover {
  background: #f0f2f5;
}

.btn-primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.btn-primary:hover {
  background: var(--accent-soft);
  color: var(--accent);
}

.btn-danger {
  background: var(--panel);
  border-color: var(--danger);
  color: var(--danger);
}

.btn-danger:hover {
  background: #fdeaea;
}

/* Calendar ---------------------------------------------------------------- */
.calendar {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  min-height: 0;
  background: var(--panel);
}

.cal-header {
  display: grid;
  grid-template-columns: 60px repeat(7, 1fr);
  border-bottom: 1px solid var(--border-strong);
  flex: 0 0 auto;
  /* leave space for the scrollbar in the body so columns stay aligned */
  padding-right: 0;
}

.time-gutter-head {
  border-right: 1px solid var(--border);
}

.day-head {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 8px 4px;
  border-right: 1px solid var(--border);
  font-size: 13px;
}

.day-head-name {
  color: var(--muted);
  text-transform: uppercase;
  font-size: 11px;
  letter-spacing: 0.04em;
}

.day-head-date {
  font-weight: 600;
  font-size: 15px;
}

.day-head.is-today {
  background: var(--today);
}

.day-head.is-today .day-head-date {
  color: var(--today-bar);
}

.cal-body {
  flex: 1 1 auto;
  display: grid;
  grid-template-columns: 60px 1fr;
  overflow-y: auto;
  overflow-x: hidden;
  min-height: 0;
  position: relative;
}

.time-gutter {
  position: relative;
  border-right: 1px solid var(--border);
}

.hour-label {
  position: absolute;
  right: 6px;
  transform: translateY(-50%);
  font-size: 11px;
  color: var(--muted);
}

.days-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  position: relative;
}

.day-col {
  position: relative;
  border-right: 1px solid var(--border);
  overflow: hidden;
}

.day-col.is-today {
  background: var(--today);
}

.hour-line {
  position: absolute;
  left: 0;
  right: 0;
  border-top: 1px solid var(--border);
  pointer-events: none;
}

/* Event blocks ------------------------------------------------------------ */
.event-block {
  position: absolute;
  background: var(--event-bg);
  border: 1px solid var(--event-bg-2);
  border-radius: 5px;
  color: #fff;
  padding: 2px 5px;
  font-size: 11px;
  line-height: 1.25;
  overflow: hidden;
  cursor: pointer;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.15);
  display: flex;
  flex-direction: column;
}

.event-block:hover {
  background: var(--event-bg-2);
  z-index: 5;
}

.event-title {
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.event-time {
  font-size: 10px;
  opacity: 0.9;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.event-ghost {
  position: absolute;
  left: 1px;
  right: 1px;
  background: rgba(47, 111, 237, 0.25);
  border: 1px dashed var(--accent);
  border-radius: 5px;
  font-size: 10px;
  color: var(--accent);
  padding: 2px 4px;
  pointer-events: none;
  z-index: 6;
  overflow: hidden;
}

/* Modal ------------------------------------------------------------------- */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
}

.modal {
  background: var(--panel);
  border-radius: 10px;
  width: 360px;
  max-width: calc(100vw - 32px);
  padding: 20px;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.25);
}

.modal-title {
  margin: 0 0 16px;
  font-size: 18px;
}

.event-form {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.field-label {
  font-size: 12px;
  color: var(--muted);
}

.field-input {
  font: inherit;
  padding: 8px 10px;
  border: 1px solid var(--border-strong);
  border-radius: 6px;
}

.field-input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}

.form-error {
  color: var(--danger);
  font-size: 13px;
}

.form-actions {
  display: flex;
  gap: 8px;
  margin-top: 4px;
}

.form-actions .btn-primary {
  margin-right: auto;
}
"}

