{"path": "backend/src/db.js", "content": "import { PGlite } from '@electric-sql/pglite';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

// Persist PGLite to local disk so events survive a server restart.
const DATA_DIR = process.env.PGLITE_DIR || path.join(__dirname, '..', 'data', 'pgdata');

let dbInstance = null;

/**
 * Returns a singleton PGLite instance, creating the schema on first use.
 */
export async function getDb() {
  if (dbInstance) return dbInstance;

  const db = new PGlite(DATA_DIR);
  await db.waitReady;

  await db.exec(`
    CREATE TABLE IF NOT EXISTS events (
      id        SERIAL PRIMARY KEY,
      title     TEXT NOT NULL,
      start_at  TIMESTAMPTZ NOT NULL,
      end_at    TIMESTAMPTZ NOT NULL,
      CONSTRAINT end_after_start CHECK (end_at > start_at)
    );
  `);

  dbInstance = db;
  return dbInstance;
}
"}

{"path": "backend/src/events.js", "content": "import { getDb } from './db.js';

/**
 * Validate and normalize event input.
 * Returns { ok: true, value } or { ok: false, error }.
 */
export function validateEventInput(body) {
  if (body === null || typeof body !== 'object') {
    return { ok: false, error: 'Request body must be a JSON object' };
  }

  const title = typeof body.title === 'string' ? body.title.trim() : '';
  if (title.length === 0) {
    return { ok: false, error: 'Title must be a non-empty string' };
  }

  const start = parseDate(body.start_at);
  if (!start) {
    return { ok: false, error: 'start_at must be a valid ISO timestamp' };
  }

  const end = parseDate(body.end_at);
  if (!end) {
    return { ok: false, error: 'end_at must be a valid ISO timestamp' };
  }

  if (!(end.getTime() > start.getTime())) {
    return { ok: false, error: 'end_at must be after start_at' };
  }

  return {
    ok: true,
    value: {
      title,
      start_at: start.toISOString(),
      end_at: end.toISOString(),
    },
  };
}

function parseDate(value) {
  if (typeof value !== 'string' || value.trim() === '') return null;
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return null;
  return d;
}

function rowToEvent(row) {
  return {
    id: row.id,
    title: row.title,
    start_at: new Date(row.start_at).toISOString(),
    end_at: new Date(row.end_at).toISOString(),
  };
}

/**
 * Return all events overlapping [start, end).
 * Overlap test: event.start_at < end AND event.end_at > start.
 */
export async function listEventsInRange(startIso, endIso) {
  const db = await getDb();
  const result = await db.query(
    `SELECT id, title, start_at, end_at
       FROM events
      WHERE start_at < $1 AND end_at > $2
      ORDER BY start_at ASC, end_at ASC, id ASC`,
    [endIso, startIso]
  );
  return result.rows.map(rowToEvent);
}

export async function createEvent({ title, start_at, end_at }) {
  const db = await getDb();
  const result = await db.query(
    `INSERT INTO events (title, start_at, end_at)
     VALUES ($1, $2, $3)
     RETURNING id, title, start_at, end_at`,
    [title, start_at, end_at]
  );
  return rowToEvent(result.rows[0]);
}

export async function updateEvent(id, { title, start_at, end_at }) {
  const db = await getDb();
  const result = await db.query(
    `UPDATE events
        SET title = $1, start_at = $2, end_at = $3
      WHERE id = $4
      RETURNING id, title, start_at, end_at`,
    [title, start_at, end_at, id]
  );
  if (result.rows.length === 0) return null;
  return rowToEvent(result.rows[0]);
}

export async function deleteEvent(id) {
  const db = await getDb();
  const result = await db.query(
    `DELETE FROM events WHERE id = $1 RETURNING id`,
    [id]
  );
  return result.rows.length > 0;
}
"}

{"path": "backend/src/server.js", "content": "import express from 'express';
import cors from 'cors';
import { getDb } from './db.js';
import {
  validateEventInput,
  listEventsInRange,
  createEvent,
  updateEvent,
  deleteEvent,
} from './events.js';

const PORT = process.env.PORT || 3001;

const app = express();
app.use(cors());
app.use(express.json());

function isValidIso(value) {
  if (typeof value !== 'string' || value.trim() === '') return false;
  const d = new Date(value);
  return !Number.isNaN(d.getTime());
}

app.get('/api/health', (_req, res) => {
  res.json({ ok: true });
});

// GET /api/events?start=<iso>&end=<iso>
app.get('/api/events', async (req, res, next) => {
  try {
    const { start, end } = req.query;
    if (!isValidIso(start) || !isValidIso(end)) {
      return res
        .status(400)
        .json({ error: 'start and end query params must be valid ISO timestamps' });
    }
    const startIso = new Date(start).toISOString();
    const endIso = new Date(end).toISOString();
    if (!(new Date(endIso).getTime() > new Date(startIso).getTime())) {
      return res.status(400).json({ error: 'end must be after start' });
    }
    const events = await listEventsInRange(startIso, endIso);
    res.json(events);
  } catch (err) {
    next(err);
  }
});

// POST /api/events
app.post('/api/events', async (req, res, next) => {
  try {
    const validation = validateEventInput(req.body);
    if (!validation.ok) {
      return res.status(400).json({ error: validation.error });
    }
    const event = await createEvent(validation.value);
    res.status(201).json(event);
  } catch (err) {
    next(err);
  }
});

// PUT /api/events/:id
app.put('/api/events/:id', async (req, res, next) => {
  try {
    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id <= 0) {
      return res.status(400).json({ error: 'Invalid event id' });
    }
    const validation = validateEventInput(req.body);
    if (!validation.ok) {
      return res.status(400).json({ error: validation.error });
    }
    const event = await updateEvent(id, validation.value);
    if (!event) {
      return res.status(404).json({ error: 'Event not found' });
    }
    res.json(event);
  } catch (err) {
    next(err);
  }
});

// DELETE /api/events/:id
app.delete('/api/events/:id', async (req, res, next) => {
  try {
    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id <= 0) {
      return res.status(400).json({ error: 'Invalid event id' });
    }
    const deleted = await deleteEvent(id);
    if (!deleted) {
      return res.status(404).json({ error: 'Event not found' });
    }
    res.status(204).end();
  } catch (err) {
    next(err);
  }
});

// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
  console.error(err);
  res.status(500).json({ error: 'Internal server error' });
});

async function main() {
  // Initialize DB (creates schema) before accepting traffic.
  await getDb();
  app.listen(PORT, () => {
    console.log(`Week-calendar backend listening on http://localhost:${PORT}`);
  });
}

main().catch((err) => {
  console.error('Failed to start server:', err);
  process.exit(1);
});

export { app };
"}

